#include <zephyr/drivers/fuel_gauge.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/logging/log.h>
#include <zephyr/kernel.h>

#include "bq27z746.h"

LOG_MODULE_REGISTER(BQ27Z746, CONFIG_FUEL_GAUGE_LOG_LEVEL);

struct bq27z746_data {
	const struct device *i2c;
	uint16_t addr;
};

static int bq27z746_read_reg(const struct device *dev, uint8_t reg_addr, uint16_t *val)
{
	struct bq27z746_data *data = dev->data;
	uint8_t buf[2];
	int ret;

	ret = i2c_write_read(data->i2c, data->addr, &reg_addr, 1, buf, 2);
	if (ret < 0) {
		LOG_ERR("Failed to read register 0x%02x: %d", reg_addr, ret);
		return ret;
	}

	/* BQ27Z746 data registers are 16-bit, LSB first */
	*val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);

	return 0;
}

static int bq27z746_get_property(const struct device *dev,
				  enum fuel_gauge_prop_type prop,
				  union fuel_gauge_prop_val *val)
{
	int ret;
	uint16_t reg_val;

	switch (prop) {
	case FUEL_GAUGE_PROP_VOLTAGE:
		ret = bq27z746_read_reg(dev, BQ27Z746_REG_VOLTAGE, &reg_val);
		if (ret < 0) {
			return ret;
		}
		val->voltage = (int32_t)reg_val;
		break;
	case FUEL_GAUGE_PROP_CURRENT:
		ret = bq27z746_read_reg(dev, BQ27Z746_REG_CURRENT, &reg_val);
		if (ret < 0) {
			return ret;
		}
		val->current = (int32_t)(int16_t)reg_val; /* Current can be negative */
		break;
	case FUEL_GAUGE_PROP_AVG_CURRENT:
		ret = bq27z746_read_reg(dev, BQ27Z746_REG_AVG_CURRENT, &reg_val);
		if (ret < 0) {
			return ret;
		}
		val->avg_current = (int32_t)(int16_t)reg_val;
		break;
	case FUEL_GAUGE_PROP_TEMP:
		ret = bq27z746_read_reg(dev, BQ27Z746_REG_TEMP, &reg_val);
		if (ret < 0) {
			return ret;
		}
		val->temp = (int32_t)reg_val; /* Typically in 0.1K or 0.1C */
		break;
	case FUEL_GAUGE_PROP_CYCLE_COUNT:
		ret = bq27z746_read_reg(dev, BQ27Z746_REG_CYCLE_COUNT, &reg_val);
		if (ret < 0) {
			return ret;
		}
		val->cycle_count = reg_val;
		break;
	case FUEL_GAUGE_PROP_STATE_OF_CHARGE:
		ret = bq27z746_read_reg(dev, BQ27Z746_REG_SOC, &reg_val);
		if (ret < 0) {
			return ret;
		}
		val->state_of_charge = reg_val;
		break;
	case FUEL_GAUGE_PROP_FULL_CHARGE_CAPACITY:
		ret = bq27z746_read_reg(dev, BQ27Z746_REG_FULL_CHARGE_CAPACITY, &reg_val);
		if (ret < 0) {
			return ret;
		}
		val->full_charge_capacity = reg_val;
		break;
	case FUEL_GAUGE_PROP_REMAINING_CAPACITY:
		ret = bq27z746_read_reg(dev, BQ27Z746_REG_REM_CAPACITY, &reg_val);
		if (ret < 0) {
			return ret;
		}
		val->remaining_capacity = reg_val;
		break;
	case FUEL_GAUGE_PROP_DESIGN_CAPACITY:
		ret = bq27z746_read_reg(dev, BQ27Z746_REG_DESIGN_CAPACITY, &reg_val);
		if (ret < 0) {
			return ret;
		}
		val->design_capacity = reg_val;
		break;
	case FUEL_GAUGE_PROP_SOH:
		ret = bq27z746_read_reg(dev, BQ27Z746_REG_SOH, &reg_val);
		if (ret < 0) {
			return ret;
		}
		val->state_of_health = reg_val;
		break;
	default:
		return -ENOTSUP;
	}

	return 0;
}

static int bq27z746_init(const struct device *dev)
{
	struct bq27z746_data *data = dev->data;
	const struct i2c_dt_spec *i2c_spec = dev->config;

	data->i2c = i2c_spec->bus;
	data->addr = i2c_spec->addr;

	if (!device_is_ready(data->i2c)) {
		LOG_ERR("I2C bus %s not ready", data->i2c->name);
		return -ENODEV;
	}

	LOG_INF("BQ27Z746 initialized on I2C bus %s at address 0x%x",
		data->i2c->name, data->addr);

	return 0;
}

static const struct fuel_gauge_driver_api bq27z746_driver_api = {
	.get_property = bq27z746_get_property,
};

#define BQ27Z746_DEFINE(inst)																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																																						
